package ar.com.miflix.admin

import com.google.gson.*
import org.junit.Test
import org.junit.Assert.*
import java.io.File
import okhttp3.OkHttpClient
import okhttp3.mockwebserver.MockWebServer
import okhttp3.mockwebserver.MockResponse

class AdminTest {
    private fun item(type:String="pelicula",id:String="movie-1")=JsonObject().apply {
        addProperty("id",id);addProperty("tipo",type);addProperty("titulo","Título");addProperty("tmdb_id",42)
        addProperty("trailer_url","https://youtu.be/original");add("unknown",JsonObject().apply {addProperty("future",true)})
        add("temporadas",JsonArray())
    }
    private fun catalog(vararg entries:JsonObject)=JsonObject().apply {addProperty("schema_version",1);addProperty("generated_at","old");addProperty("unknown_root",true);add("items",JsonArray().apply {entries.forEach {add(it)}})}
    class Memory:StateStore {var value:JsonObject?=null;override fun read()=value?.deepCopy();override fun write(state:JsonObject){value=state.deepCopy()}}
    class Fake(var cat:JsonObject):AdminRemote {
        var downloadFails=false;var uploadFails=false;var uploads=0
        override fun download():JsonObject {if(downloadFails) error("red caída");return cat.deepCopy()}
        override fun publish(catalog:JsonObject) {if(uploadFails) error("falló publicación");uploads++;cat=catalog.deepCopy()}
    }
    private fun cp()=TelegramLinks.checkpoint(item(),"https://t.me/c/123/7/99?single&thread=7#x")
    @Test fun parsesSchemaOneAndAllCategories(){assertEquals(3,CatalogRules.items(CatalogRules.parse(catalog(item(),item("serie","s"),item("anime","a")).toString())).size)}
    @Test fun rejectsOtherSchema(){assertThrows(IllegalArgumentException::class.java){CatalogRules.parse("{\"schema_version\":2,\"items\":[]}")}}
    @Test fun rejectsHtml(){assertThrows(IllegalStateException::class.java){CatalogRules.parse("<html>error</html>")}}
    @Test fun rejectsMalformedItems(){assertThrows(IllegalArgumentException::class.java){CatalogRules.parse("{\"schema_version\":1,\"items\":[1]}")}}
    @Test fun rejectsRepeatedIds(){assertThrows(IllegalArgumentException::class.java){CatalogRules.parse(catalog(item(),item()).toString())}}
    @Test fun preserveUnknownRootItemAndUntouchedCategories(){val root=catalog(item(),item("serie","s"),item("anime","a"));val edit=item().apply {addProperty("titulo","Editado")};val out=CatalogRules.save(root,edit);assertEquals(root.get("unknown_root"),out.get("unknown_root"));assertEquals(root.array("items")[1],CatalogRules.items(out).first {it.text("id")=="s"});assertEquals(root.array("items")[2],CatalogRules.items(out).first {it.text("id")=="a"});assertEquals(edit.get("unknown"),CatalogRules.items(out).first {it.text("id")=="movie-1"}.get("unknown"));assertEquals("https://youtu.be/original",CatalogRules.items(out).first {it.text("id")=="movie-1"}.text("trailer_url"))}
    @Test fun sourceJsonNeverMutated(){val root=catalog(item());val before=root.toString();CatalogRules.save(root,item());assertEquals(before,root.toString())}
    @Test fun duplicateSameIdOnNewCreation(){assertNotNull(CatalogRules.duplicate(catalog(item()),item(),null));assertNull(CatalogRules.duplicate(catalog(item()),item()))}
    @Test fun duplicateByTmdbNotFuzzyTitle(){val candidate=item(id="other").apply {addProperty("titulo","Distinto")};assertNotNull(CatalogRules.duplicate(catalog(item()),candidate));candidate.addProperty("tmdb_id",99);assertNull(CatalogRules.duplicate(catalog(item()),candidate))}
    @Test fun exactTopicUrl(){val url="https://t.me/c/123/7/99?single&thread=7#x";assertEquals(url,TelegramLinks.valid(url));assertEquals(99L,TelegramLinks.messageId(url));assertEquals(url,cp().text("telegram_url"))}
    @Test fun unsafeAndInviteLinksRejected(){listOf("https://evil.test/123","javascript:alert(1)","https://t.me/+invite","https://user@t.me/channel/2","https://t.me/channel/0").forEach {assertNull(TelegramLinks.valid(it))}}
    @Test fun shareMultipleLinks(){assertEquals(2,TelegramLinks.extract("A https://t.me/c/123/1 y https://t.me/public/2").size)}
    @Test fun checkpointIndependentOfPlayback(){val old=item().apply {addProperty("telegram_url","https://t.me/c/123/1")};val checkpoint=TelegramLinks.checkpoint(old,"https://t.me/c/123/2");assertEquals("https://t.me/c/123/1",old.text("telegram_url"));assertEquals("https://t.me/c/123/2",checkpoint.text("telegram_url"))}
    @Test fun seasonMergePreservesUrlsUnknownAndIds(){val base=item("serie");val previous=JsonParser.parseString("{\"numero\":0,\"extra\":true,\"episodios\":[{\"numero\":1,\"tmdb_id\":9,\"telegram_url\":\"https://t.me/c/123/1\",\"other\":true}]}").asJsonObject;base.array("temporadas").add(previous);val new=JsonParser.parseString("{\"numero\":0,\"episodios\":[{\"numero\":1,\"tmdb_id\":9,\"titulo\":\"Nuevo\"}]}").asJsonObject;val out=CatalogRules.mergeSeason(base,new).array("temporadas")[0].asJsonObject;assertTrue(out.get("extra").asBoolean);val ep=out.array("episodios")[0].asJsonObject;assertEquals("https://t.me/c/123/1",ep.text("telegram_url"));assertTrue(ep.get("other").asBoolean);assertEquals("Nuevo",ep.text("titulo"))}
    @Test fun emptySeasonResponseDoesNotEraseEpisodes(){val base=item("serie");base.array("temporadas").add(JsonParser.parseString("{\"numero\":1,\"episodios\":[{\"numero\":1}]}").asJsonObject);assertEquals(1,CatalogRules.mergeSeason(base,JsonParser.parseString("{\"numero\":1,\"episodios\":[]}").asJsonObject).array("temporadas")[0].asJsonObject.array("episodios").size())}
    @Test fun animeEnrichmentKeepsIdentityAndOnlySelectedGroups(){val base=item("anime","anime-5").apply {addProperty("anilist_id",5);addProperty("fuente_principal","AniList");addProperty("sinopsis","Original");addProperty("poster_url","original");add("fuentes_metadata",JsonObject())};val candidate=item("anime","anime-tmdb-42").apply {addProperty("poster_url","new");addProperty("sinopsis","No importar");addProperty("fondo_url","fondo")};val out=Enrichment.apply(base,candidate,setOf("fondo"));assertEquals("anime-5",out.text("id"));assertEquals("AniList",out.text("fuente_principal"));assertEquals("Original",out.text("sinopsis"));assertEquals("original",out.text("poster_url"));assertEquals("fondo",out.text("fondo_url"));assertEquals(5L,out.number("anilist_id"));assertEquals(42L,out.number("tmdb_id"))}
    @Test fun versionUpdatePreservesMetadataAndUpdatesMovieEpisode(){val old=item().apply {addProperty("sinopsis","Manual");array("temporadas").add(JsonParser.parseString("{\"numero\":0,\"episodios\":[{\"numero\":1,\"telegram_url\":\"https://t.me/c/123/1\"}]}").asJsonObject)};val out=CatalogRules.updateVersion(old,"https://t.me/c/123/2","Latino","1080p");assertEquals("Manual",out.text("sinopsis"));assertEquals("movie-1",out.text("id"));assertEquals("https://t.me/c/123/2",out.array("temporadas")[0].asJsonObject.array("episodios")[0].asJsonObject.text("telegram_url"))}
    @Test fun firstDownloadUnlocks(){val repo=AdminRepository(Memory());assertFalse(repo.writable);repo.refresh(Fake(catalog(item())));assertTrue(repo.writable);assertFalse(repo.pending)}
    @Test fun failedDownloadKeepsValidCacheAndLocks(){val store=Memory();val remote=Fake(catalog(item()));val repo=AdminRepository(store);repo.refresh(remote);val before=store.value.toString();remote.downloadFails=true;assertThrows(IllegalStateException::class.java){repo.refresh(remote)};assertEquals(before,store.value.toString());assertFalse(repo.writable)}
    @Test fun saveWithoutDownloadForbidden(){assertThrows(IllegalStateException::class.java){AdminRepository(Memory()).saveItem(item())}}
    @Test fun publicationFailurePreservesPending(){val repo=AdminRepository(Memory());val remote=Fake(catalog(item()));repo.refresh(remote);repo.saveItem(item().apply {addProperty("titulo","Nuevo")});remote.uploadFails=true;assertThrows(IllegalStateException::class.java){repo.publish(remote)};assertTrue(repo.pending);assertEquals("Nuevo",CatalogRules.items(repo.catalog!!)[0].text("titulo"))}
    @Test fun publicationSuccessClearsOnlyAfterAck(){val repo=AdminRepository(Memory());val remote=Fake(catalog(item()));repo.refresh(remote);repo.saveItem(item(),cp());repo.publish(remote);assertFalse(repo.pending);assertEquals(1,remote.uploads)}
    @Test fun localCheckpointNeedsNoRemoteAckOrReupload(){val store=Memory();val repo=AdminRepository(store);val remote=Fake(catalog(item()));repo.refresh(remote);repo.saveItem(item(),cp());repo.publish(remote);assertFalse(repo.pending);assertEquals(cp().text("telegram_url"),repo.checkpoint("pelicula")!!.text("telegram_url"));repo.publish(remote);assertEquals(1,remote.uploads)}
    @Test fun processRestartPreservesPendingAndDraft(){val store=Memory();val remote=Fake(catalog(item()));val repo=AdminRepository(store);repo.refresh(remote);repo.saveItem(item().apply {addProperty("titulo","Pendiente")});repo.persistDraft(item().apply {addProperty("sinopsis","Borrador")});val restarted=AdminRepository(store);assertTrue(restarted.pending);assertFalse(restarted.writable);restarted.refresh(remote);assertEquals("Pendiente",CatalogRules.items(restarted.catalog!!)[0].text("titulo"));assertEquals("Borrador",restarted.draft()!!.text("sinopsis"))}
    @Test fun remoteChangeWithPendingBlocksAndPreserves(){val store=Memory();val remote=Fake(catalog(item()));val repo=AdminRepository(store);repo.refresh(remote);repo.saveItem(item());remote.cat=catalog(item().apply {addProperty("titulo","Cambio PC")});val before=store.value.toString();assertThrows(IllegalStateException::class.java){repo.refresh(remote)};assertFalse(repo.writable);assertEquals(before,store.value.toString());repo.refresh(remote,true);assertEquals("Cambio PC",CatalogRules.items(repo.catalog!!)[0].text("titulo"));assertFalse(repo.pending)}
    @Test fun checkpointOnlyDoesNotPublishCatalog(){val repo=AdminRepository(Memory());val remote=Fake(catalog(item()));repo.refresh(remote);repo.setCheckpoint(cp());repo.publish(remote);assertEquals(0,remote.uploads)}
    @Test fun configNormalizationAndValidation(){assertEquals("https://example.test",AdminConfig("https://example.test/admin/catalogo","fake").normalized().baseUrl);assertThrows(IllegalArgumentException::class.java){AdminConfig("http://example.test","fake").normalized()};assertThrows(IllegalArgumentException::class.java){AdminConfig("https://example.test","").normalized()};assertThrows(IllegalArgumentException::class.java){AdminConfig("https://user:pass@example.test","fake").normalized()}}
    @Test fun fileEnvelopePersistsRoundTrip(){val file=File.createTempFile("miflix","json");file.delete();val store=FileStateStore(file);store.write(catalog(item()));assertEquals(catalog(item()),store.read());file.delete()}
    @Test fun publicCopyDoesNotLeakPaths(){val root=catalog(item().apply {addProperty("poster_local","C:/secret");array("temporadas").add(JsonParser.parseString("{\"numero\":0,\"episodios\":[{\"numero\":1,\"local_path\":\"C:/movie\"}]}").asJsonObject)});val out=CatalogRules.publicCopy(root);assertFalse(CatalogRules.items(out)[0].has("poster_local"));assertFalse(CatalogRules.items(out)[0].array("temporadas")[0].asJsonObject.array("episodios")[0].asJsonObject.has("local_path"));assertTrue(CatalogRules.items(root)[0].has("poster_local"))}
    @Test fun httpDownloadAndPublication(){val server=MockWebServer();server.start();try {server.enqueue(MockResponse().setBody(catalog(item()).toString()));server.enqueue(MockResponse().setBody("{\"ok\":true}"));val remote=HttpAdminRemote(AdminConfig(server.url("/").toString().trimEnd('/'),"fake"),OkHttpClient());assertEquals(1,CatalogRules.items(remote.download()).size);remote.publish(catalog(item()));assertEquals("/catalogo.json",server.takeRequest().path);val sent=server.takeRequest();assertEquals("PUT",sent.method);assertEquals("Bearer fake",sent.getHeader("Authorization"))} finally {server.shutdown()}}
    @Test fun httpHtmlErrorAndFalseAck(){val server=MockWebServer();server.start();try {server.enqueue(MockResponse().setBody("<html>error</html>"));server.enqueue(MockResponse().setBody("{\"ok\":false}"));val r=HttpAdminRemote(AdminConfig(server.url("/").toString().trimEnd('/'),"fake"),OkHttpClient());assertThrows(IllegalStateException::class.java){r.download()};assertThrows(IllegalStateException::class.java){r.publish(catalog(item()))}} finally {server.shutdown()}}
    @Test fun httpUnauthorizedRejected(){val server=MockWebServer();server.start();try {server.enqueue(MockResponse().setResponseCode(401));val r=HttpAdminRemote(AdminConfig(server.url("/").toString().trimEnd('/'),"fake"),OkHttpClient());assertThrows(SecurityException::class.java){r.publish(catalog(item()))}} finally {server.shutdown()}}
    @Test fun tmdbMovieDetailAndTrailerAsMetadata(){val server=MockWebServer();server.start();try {server.enqueue(MockResponse().setBody("{\"id\":42,\"title\":\"Película\",\"original_title\":\"Movie\",\"release_date\":\"2020-01-01\",\"genres\":[{\"name\":\"Drama\"}],\"overview\":\"Sinopsis\",\"poster_path\":\"/poster.jpg\",\"vote_average\":7.2}"));server.enqueue(MockResponse().setBody("{\"imdb_id\":\"tt123\"}"));server.enqueue(MockResponse().setBody("{\"cast\":[{\"name\":\"Actor\"}],\"crew\":[{\"job\":\"Director\",\"name\":\"Directora\"}]}"));server.enqueue(MockResponse().setBody("{\"results\":[{\"site\":\"YouTube\",\"type\":\"Trailer\",\"official\":true,\"key\":\"abc\"}]}"));server.enqueue(MockResponse().setBody("{\"logos\":[]}"));val meta=HttpMetadata(AdminConfig("https://test.invalid","fake","fake-tmdb"),OkHttpClient(),server.url("/").toString().trimEnd('/'));val out=meta.detail(SearchResult("TMDB",42,"Película","2020","",JsonObject()),"pelicula");assertEquals("pelicula-imdb-tt123",out.text("id"));assertEquals("https://www.youtube.com/watch?v=abc",out.text("trailer_url"));assertEquals("7.2/10",out.text("puntuacion"));assertEquals("Directora",out.text("direccion"))} finally {server.shutdown()}}
    @Test fun tmdbSeasonMetadata(){val server=MockWebServer();server.start();try {server.enqueue(MockResponse().setBody("{\"season_number\":0,\"episodes\":[{\"id\":9,\"episode_number\":1,\"name\":\"Especial\",\"runtime\":30,\"air_date\":\"2020-01-01\",\"still_path\":\"/a.jpg\"}]}"));val meta=HttpMetadata(AdminConfig("https://test.invalid","fake","fake-tmdb"),OkHttpClient(),server.url("/").toString().trimEnd('/'));val out=meta.season(42,0);assertEquals(0L,out.number("numero"));val e=out.array("episodios")[0].asJsonObject;assertEquals(9L,e.number("tmdb_id"));assertEquals("Especial",e.text("titulo"));assertEquals(30L,e.number("duracion"))} finally {server.shutdown()}}
    @Test fun invalidCacheDoesNotCrashOrUnlock(){val store=Memory();store.value=JsonObject().apply {add("catalog",JsonObject())};val repo=AdminRepository(store);assertNull(repo.catalog);assertFalse(repo.writable);assertTrue(repo.recoveryNotice.isNotBlank());repo.refresh(Fake(catalog(item())));assertTrue(repo.writable)}
    @Test fun brokenEnvelopeReadDoesNotCrash(){val store=object:StateStore {override fun read():JsonObject?=error("corrupt");override fun write(state:JsonObject){}};val repo=AdminRepository(store);assertFalse(repo.writable);assertNull(repo.catalog)}
    @Test fun animeEpisodeBlockDownloadsAllSeasonsBeforeMerge(){val calls=mutableListOf<Int>();val metadata=object:Metadata {override fun search(query:String,type:String,source:String)=emptyList<SearchResult>();override fun detail(result:SearchResult,type:String)=JsonObject();override fun season(id:Long,number:Int):JsonObject {calls.add(number);return JsonObject().apply {addProperty("numero",number);add("episodios",JsonArray().apply {add(JsonObject().apply {addProperty("numero",1);addProperty("titulo","Obtenido")})})}}};val candidate=item("anime").apply {addProperty("tmdb_id",42);add("temporadas",JsonArray().apply {listOf(0,1).forEach {add(JsonObject().apply {addProperty("numero",it)})}})};val result=Enrichment.withEpisodes(metadata,candidate);assertEquals(listOf(0,1),calls);assertEquals("Obtenido",result.array("temporadas")[1].asJsonObject.array("episodios")[0].asJsonObject.text("titulo"));assertEquals(0,candidate.array("temporadas")[0].asJsonObject.array("episodios").size())}

    @Test fun anilistSearchAndDetailKeepsPrimaryIdentity(){val server=MockWebServer();server.start();try {server.enqueue(MockResponse().setBody("""{"data":{"Page":{"media":[{"id":55,"idMal":null,"title":{"english":"Anime","romaji":"Original","native":"Native"},"seasonYear":2024,"genres":["Drama"],"description":"<b>Sinopsis</b>","averageScore":82,"episodes":12,"coverImage":{"extraLarge":"https://image.test/a.jpg"},"characters":{"edges":[{"role":"MAIN","node":{"name":{"full":"Personaje"}}}]},"staff":{"edges":[{"role":"Director","node":{"name":{"full":"Directora"}}}]},"trailer":{"site":"youtube","id":"abc"}}]}}}"""));val meta=HttpMetadata(AdminConfig("https://worker.test","fake"),OkHttpClient(),anilistUrl=server.url("/").toString());val found=meta.search("Anime","anime","AniList");val out=meta.detail(found.single(),"anime");assertEquals(55L,out.number("anilist_id"));assertEquals("AniList",out.text("fuente_principal"));assertEquals("Native",out.text("titulo_original"));assertEquals("Sinopsis",out.text("sinopsis"));assertEquals("82/100",out.text("puntuacion"));assertEquals("Directora",out.text("direccion"));assertNull(server.takeRequest().getHeader("Authorization"))} finally {server.shutdown()}}

}
